import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { verifySessionToken } from "@/lib/admin-auth";

const SESSION_COOKIE = "admin_session";
const ADMIN_LOGIN_PATH = "/admin/login";

/**
 * Proxy to protect /admin/* routes — checks for a valid signed session cookie.
 * Renamed from middleware.ts per Next.js 16 conventions.
 *
 * Sessions are now signed HMAC-SHA256 tokens with expiration, generated by
 * authenticateAndGetSession() and verified here using verifySessionToken().
 */
export async function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Allow the login page and its assets
  if (pathname === ADMIN_LOGIN_PATH || pathname.startsWith(ADMIN_LOGIN_PATH + "/")) {
    // If already authenticated and hitting login, redirect to events
    const sessionCookie = request.cookies.get(SESSION_COOKIE)?.value;
    if (sessionCookie && (await verifySessionToken(sessionCookie))) {
      return NextResponse.redirect(new URL("/admin/events", request.url));
    }
    return NextResponse.next();
  }

  // Check session cookie for all other /admin/* routes
  const session = request.cookies.get(SESSION_COOKIE)?.value;
  if (!session || !(await verifySessionToken(session))) {
    const loginUrl = new URL(ADMIN_LOGIN_PATH, request.url);
    loginUrl.searchParams.set("from", pathname);
    return NextResponse.redirect(loginUrl);
  }

  return NextResponse.next();
}

export const config = {
  matcher: ["/admin/:path*", "/advertising/:path*"],
};
